147:   // received, any previously installed (non-Crashpad) signal handler will be
148:   // restored and the signal reraised.
149:   static void Disable() {
150:     if (!handler_->disabled_.test_and_set()) {
151:       handler_->WakeThreads();
152:     }
153:   }
