33:     PLOG_IF(ERROR, can_log) << "waitpid";
34:     return false;
35:   }
36:   if (!WIFSTOPPED(status)) {
37:     LOG_IF(ERROR, can_log) << "process not stopped";
38:     return false;
39:   }
40:   return true;
41: }
